 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);readSharedText(intent);}
 private void readSharedText(Intent intent){CharSequence shared=intent.getCharSequenceExtra(Intent.EXTRA_TEXT);if(shared==null)shared=intent.getCharSequenceExtra(Intent.EXTRA_PROCESS_TEXT);if(shared!=null){composer.setText(shared);composer.setSelection(composer.length());}}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("session",sessionKey);out.putString("agent",agent);out.putString("draft",composer.getText().toString());}
 @Override protected void onPause(){if(readAloud!=null)readAloud.stop();super.onPause();}
 @Override protected void onDestroy(){if(readAloud!=null)readAloud.close();if(client!=null)client.stop();super.onDestroy();}
