 private void applyPalette(){String appearance=getPreferences(MODE_PRIVATE).getString("appearance","system");dark="dark".equals(appearance)||("system".equals(appearance)&&(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES);BG=dark?0xff212121:Color.WHITE;SURFACE=dark?0xff303030:0xfff4f4f4;SIDEBAR=dark?0xff171717:0xfff9f9f9;TEXT=dark?0xfff4f4f4:0xff171717;MUTED=dark?0xffa0a0a0:0xff737373;LINE=dark?0xff3c3c3c:0xffe8e8e8;getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);}
