  status=text(connectionState,12,MUTED);composer.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){updateSend();}public void afterTextChanged(Editable e){}});updateSend();
